window.MOTIF_CATALOG_CHUNKS[44]={"cards":[{"id":"MEJE-KW-002184","row_version":3,"title":"아시아계 인물을 어수룩함으로만 그리기","original":"Asian Airhead","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"아시아계 캐릭터에게 지적 능력이 낮다는 역할을 몰아 주어 다른 고정관념을 뒤집는 듯한 묘사. 어느 방향이든 출신으로 성격을 정하는 단순화를 비판적으로 읽는다. 반대 이미지인 아시아계 인물을 공부벌레로만 그리기 역시 출신으로 성격을 정하는 단순화다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-002184/index.html"},{"id":"MEJE-KW-002185","row_version":2,"title":"아시아계 인물을 공부벌레로만 그리기","original":"Asian and Nerdy","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"아시아계 캐릭터를 성적·기술·학업에만 몰두하는 인물로 반복 배치한다. 개인의 관심사와 삶을 출신 집단의 성질로 환원하는 고정관념을 살핀다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-002185/index.html"},{"id":"MEJE-KW-002187","row_version":2,"title":"아시아인 전 연인과 숨겨진 아이를 소품처럼 쓰기","original":"Asian Babymama","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"영웅의 과거를 드러내려고 아시아인 전 연인과 뒤늦게 밝혀지는 아이를 배치하는 묘사. 여성 인물의 삶을 남성 주인공의 놀라운 출생 비밀로만 소비하는지 비판적으로 살핀다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-002187/index.html"},{"id":"MEJE-KW-002188","row_version":2,"title":"아시아계 얼굴에 뻐드렁니를 덧그린 희화화","original":"Asian Buck Teeth","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"아시아계 인물을 한눈에 알아보게 하겠다며 치아와 얼굴을 과장하는 오래된 인종적 캐리커처. 실제 외모의 특징으로 취급하지 않고 차별적 시각 표현으로 기록한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-002188/index.html"},{"id":"MEJE-KW-002189","row_version":1,"title":"아시아 요리사를 칼춤으로만 그리기","original":"Asian Cleaver Fever","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"아시아 음식을 만드는 인물이 조리보다 무술 같은 칼놀림을 과장해 보여 주는 묘사. 서로 다른 음식 문화와 요리 기술을 하나의 이국적 볼거리로 줄이는 방식을 살핀다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-002189/index.html"},{"id":"MEJE-KW-002190","row_version":1,"title":"아시아계 운전자를 서툴다고 그리기","original":"Asian Drivers","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"운전 실수나 무모함을 아시아계 인물의 출신 탓으로 설명하는 고정관념. 실제 운전 능력에 관한 사실로 받아들이지 않고 차별적 농담의 구조를 다룬다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-002190/index.html"},{"id":"MEJE-KW-002191","row_version":3,"title":"동아시아 이야기의 여우 영물","original":"Asian Fox Spirit","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":null,"parent_id":null,"tag_path":["ML-F29","ML-T02369"],"summary":"여우가 사람으로 변하거나 영적 능력을 지닌 존재로 등장하는 전승과 창작 모티프. 한국의 구미호, 일본의 여우 신앙, 중국의 여우 이야기를 같은 존재로 합치지 않고 차이를 살핀다. 한국의 구미호는 이 넓은 여우 모티프 가운데 하나이며 다른 지역의 전승과 구분한다.","accent":"#7B876E","tab":"#778F70","facet":"기원·전승·참조","bookmark":"동아시아 전승","entry_url":"cards/MEJE-KW-002191/index.html"},{"id":"MEJE-KW-002192","row_version":1,"title":"아시아계 여성을 성매매 이미지로 환원하기","original":"Asian Hooker Stereotype","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"아시아계 여성 인물을 실제 직업과 무관하게 성적 서비스의 이미지로 읽게 하는 묘사. 인종과 성별을 겹쳐 대상화하는 편견으로 다룬다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-002192/index.html"},{"id":"MEJE-KW-002193","row_version":2,"title":"건물 입구를 지키는 중국식 사자상","original":"Asian Lion Dogs","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":null,"parent_id":null,"tag_path":["ML-F29","ML-T02369"],"summary":"궁궐·사찰·묘역의 입구에 한 쌍으로 놓이는 사자 모양 수호 조각. 작품에서는 공간의 권위와 보호의 의미를 보여 주는 시각 표지가 된다. 건축물의 수호 상징은 동아시아 전승 안에서도 지역별 표현이 다르다.","accent":"#7B876E","tab":"#778F70","facet":"기원·전승·참조","bookmark":"동아시아 전승","entry_url":"cards/MEJE-KW-002193/index.html"},{"id":"MEJE-KW-002194","row_version":1,"title":"중국계 관광객을 무례함으로만 그리기","original":"Asian Rudeness","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"중국계 관광객을 시끄럽고 무례한 행동의 집단으로 단순화하는 묘사. 개별 행동을 국적이나 혈통의 본성으로 일반화하는 편견을 드러낸다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-002194/index.html"},{"id":"MEJE-KW-002195","row_version":2,"title":"손모양과 주문으로 힘을 부르는 장면","original":"Asian Rune Chant","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":null,"parent_id":null,"tag_path":["ML-F29","ML-T02369"],"summary":"동아시아 종교·민속에서 전해진 손인과 진언의 이미지를 창작물의 마법 발동 장면에 쓴다. 전승의 출처와 작품 속 재해석을 구분한다.","accent":"#7B876E","tab":"#778F70","facet":"기원·전승·참조","bookmark":"동아시아 전승","entry_url":"cards/MEJE-KW-002195/index.html"},{"id":"MEJE-KW-002196","row_version":2,"title":"아시아인이 반려동물을 먹는다는 편견","original":"Asians Eat Pets","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"아시아계 인물을 반려동물을 먹는 사람으로 묘사해 낯설고 잔혹하다고 느끼게 하는 인종적 고정관념. 지역별 식문화의 실제 차이와 차별적 일반화를 구분한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-002196/index.html"},{"id":"MEJE-KW-002197","row_version":2,"title":"아시아계 인물을 차 애호가로만 그리기","original":"Asians Love Tea","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"아시아계 캐릭터에게 차 마시기를 전통과 지혜의 표지처럼 반복해서 부여한다. 개인의 취향과 지역마다 다른 음료 문화를 하나의 민족적 특성으로 환원하는지 살핀다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-002197/index.html"},{"id":"MEJE-KW-002198","row_version":2,"title":"아시아계 인물의 영어 발음을 희화화하기","original":"Asian Speekee Engrish","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"아시아계 화자의 영어를 몇 가지 발음 치환과 어색한 문장으로 단순화해 웃음을 만드는 묘사. 실제 화자와 언어별 차이를 지우는 차별적 표현으로 기록한다. 언어의 습득과 사용을 현실과 다르게 그리기 가운데 출신 집단을 희화화하는 사례다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-002198/index.html"},{"id":"MEJE-KW-002199","row_version":1,"title":"아시아계 이민자를 가게 주인으로만 그리기","original":"Asian Store-Owner","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"아시아계 인물을 가족이 운영하는 작은 상점의 주인 역할에만 반복해서 배치한다. 직업과 말투를 출신 집단의 정형으로 만드는 표현을 비판적으로 살핀다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-002199/index.html"},{"id":"MEJE-KW-002200","row_version":3,"title":"관객을 향해 흘리는 짧은 독백","original":"Aside Comment","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 화면이나 무대 바깥을 향해 상황을 짧게 평하지만 관객의 존재를 분명히 인정하지는 않는다. 장면 속 대화와 완전한 제4의 벽 파괴 사이에 놓인 말이다. 말없이 관객과 반응을 나누는 카메라를 향한 짧은 눈짓과 구분한다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002200/index.html"},{"id":"MEJE-KW-002201","row_version":2,"title":"카메라를 향한 짧은 눈짓","original":"Aside Glance","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물이 어이없는 상황에서 잠시 화면을 바라봐 관객과 반응을 나눈다. 말을 하지 않아도 장면의 우스움이나 당혹감을 전달한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-002201/index.html"},{"id":"MEJE-KW-002202","row_version":2,"title":"기술·모험·사회로 나눈 과학소설","original":"Asimov's Three Kinds of Science Fiction","aliases":[],"kind":"keyword","facet_id":"ML-F01","node_kind":null,"parent_id":null,"tag_path":["ML-F01"],"summary":"과학소설에서 발명 자체, 발명이 낳는 모험, 발명이 바꾸는 사회 가운데 무엇이 이야기의 중심인지 구분하는 분류. 한 작품이 한 갈래에만 들어가야 한다는 규칙은 아니다.","accent":"#5C7669","tab":"#9A6A55","facet":"개념 유형","bookmark":"분류축","entry_url":"cards/MEJE-KW-002202/index.html"},{"id":"MEJE-KW-002203","row_version":1,"title":"사회운동 집단을 우스운 인물들로만 그리기","original":"Asinine Activist Group","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"공동의 요구를 가진 집단을 무능·말다툼·과장된 항의의 이미지로만 표현한다. 정당한 문제 제기까지 조롱의 대상으로 지우는지 비판적으로 살핀다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-002203/index.html"},{"id":"MEJE-KW-002204","row_version":1,"title":"기대하던 활동 대신 지루한 일을 시키기","original":"Asinine Alternate Activity","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 흥미로운 일을 하려다 제지당하고 재미없는 대체 활동을 배정받는다. 기대와 실제 경험의 간격이 실망과 웃음을 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002204/index.html"},{"id":"MEJE-KW-002205","row_version":1,"title":"뻔한 질문에 엉뚱한 대답을 돌려주기","original":"Ask a Stupid Question...","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"답이 눈앞에 있는데도 질문하는 사람에게 상대가 엉뚱하거나 짓궂은 답을 한다. 질문의 불필요함을 대화의 반전으로 드러낸다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002205/index.html"},{"id":"MEJE-KW-002206","row_version":1,"title":"도움을 청하면 약해진다고 믿기","original":"Asking for Help Is Weak","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"인물이 타인에게 부탁하는 일을 무능이나 의존의 표시로 여겨 혼자 버틴다. 자립의 가치가 필요한 협력까지 막을 때 갈등이 생긴다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-002206/index.html"},{"id":"MEJE-KW-002207","row_version":2,"title":"수업 중 잠이 드는 인물","original":"Asleep in Class","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"학생이 피로나 지루함을 이기지 못해 수업 시간에 잠든다. 밤에 벌어진 사건의 여파나 학교생활의 부담을 짧은 장면으로 드러낸다. 수행하는 듯 보이지만 졸고 있는 명상하는 줄 알았는데 잠든 인물과 잠의 맥락이 다르다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002207/index.html"},{"id":"MEJE-KW-002208","row_version":1,"title":"명상하는 줄 알았는데 잠든 인물","original":"Asleep, Not Meditating","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"고요히 앉은 인물을 수행 중인 것으로 여겼다가 코를 골거나 깨우자 잠든 사실이 드러난다. 겉모습과 실제 상태의 차이가 웃음을 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002208/index.html"},{"id":"MEJE-KW-002209","row_version":2,"title":"장면에 따라 치명성이 달라지는 공격","original":"As Lethal as It Needs to Be","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"같은 무기와 동작이 어떤 인물에게는 가벼운 타격이고 다른 인물에게는 치명상이 된다. 공격의 설정 수치보다 이야기에서 필요한 생존 결과가 앞서는 묘사다. 방어구의 효력을 약하게 그린 갑옷이 제 구실을 못하는 전투와 함께 전투의 위험도를 바꾼다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-002209/index.html"},{"id":"MEJE-KW-002210","row_version":1,"title":"뜻보다 외국어처럼 들리는 소리 택하기","original":"As Long as It Sounds Foreign","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"실제 언어의 문법과 맥락을 확인하지 않고 낯선 소리만 모아 외국어 대사처럼 쓴다. 특정 언어의 화자를 희화화하거나 세계의 언어 설정을 흐릴 수 있다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-002210/index.html"},{"id":"MEJE-KW-002211","row_version":2,"title":"악이 남아 있는 한 사라지지 않는 적","original":"As Long as There Is Evil","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"세계에 악의가 존재하는 한 적도 완전히 죽지 않거나 되돌아온다는 규칙. 한 전투의 승리와 악의 근원을 바꾸는 일 사이에 간격을 둔다. 적이 되살아나는 규칙은 한 사람이 남아 있으면 저항은 이어지기와 지속의 방향이 다르다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-002211/index.html"},{"id":"MEJE-KW-002212","row_version":1,"title":"한 사람이 남아 있으면 저항은 이어지기","original":"As Long as There Is One Man","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18"],"summary":"영웅이 패배해도 뜻을 잇는 사람이 한 명이라도 나와 저항을 계속한다. 한 인물의 생존보다 공동의 결의가 이야기의 희망을 지탱한다.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/MEJE-KW-002212/index.html"},{"id":"MEJE-KW-002213","row_version":1,"title":"장소의 일부를 모아 보여 주는 도입 장면","original":"Aspect Montage","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"공간 전체를 한 번에 펼치지 않고 사물과 표면의 짧은 화면을 이어 장소의 분위기를 만든다. 관객이 조각난 단서로 공간을 떠올리게 하는 연출이다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-002213/index.html"},{"id":"MEJE-KW-002214","row_version":2,"title":"이야기 구간마다 화면 비율이 바뀌기","original":"Aspect Ratio Switch","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"시대·세계·기억의 층이 달라질 때 화면의 가로세로 비율을 바꾼다. 같은 장면 안에서도 프레임 크기의 변화를 통해 전환을 느끼게 할 수 있다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-002214/index.html"},{"id":"MEJE-KW-002215","row_version":2,"title":"중요 인물을 노린 암살 시도","original":"Assassination Attempt","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07","ML-T00776","ML-T00784"],"summary":"권력자나 상징적 인물을 비밀리에 죽이려는 계획이 실행되거나 저지된다. 성공 여부와 관계없이 보안·배후·후폭풍을 이야기의 갈등으로 만든다. 암살의 표적이 반격하는 암살 대상이 되레 암살자를 제압하기와 결과를 비교할 수 있다.","accent":"#9B7160","tab":"#7D8FA3","facet":"사건·행동","bookmark":"암살","entry_url":"cards/MEJE-KW-002215/index.html"},{"id":"MEJE-KW-002216","row_version":3,"title":"특정 인물을 제거하는 게임 부가 임무","original":"Assassination Sidequest","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"주된 목표와 별개로 지정된 인물을 은밀히 제거하라는 선택 임무를 준다. 목표의 위치와 감시망을 파악하는 과정이 보상과 위험을 만든다. 주된 사건에 해당하는 중요 인물을 노린 암살 시도를 게임의 선택 과제로 옮긴 형태다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-002216/index.html"},{"id":"MEJE-KW-002217","row_version":1,"title":"손목에 단 발톱형 암살 무기","original":"Assassin Claws","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"손이나 손목에 고정한 날카로운 발톱형 장비를 암살자의 상징처럼 사용한다. 무기의 실용성뿐 아니라 가까이 접근해야 하는 전투 방식을 보여 준다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-002217/index.html"},{"id":"MEJE-KW-002218","row_version":2,"title":"암살 대상이 되레 암살자를 제압하기","original":"Assassin Outclassin'","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"준비된 기습을 맞은 인물이 도망치거나 반격해 암살자의 계획을 무너뜨린다. 보호받아야 할 표적으로 보이던 사람이 전투의 주도권을 되찾는다. 성공한 뒤에도 조직이 임무를 끝낸 암살자를 배신하기처럼 위험이 끝나지 않을 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002218/index.html"},{"id":"MEJE-KW-002219","row_version":1,"title":"조직이 임무를 끝낸 암살자를 배신하기","original":"Assassins Are Always Betrayed","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"고용주나 조직이 비밀을 지우거나 권력을 차지하려 자신이 보낸 암살자를 제거하려 한다. 임무의 진짜 목적과 충성의 대가가 뒤늦게 드러난다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-002219/index.html"},{"id":"MEJE-KW-002220","row_version":1,"title":"작업 속도가 빨라져 손이 모자라기","original":"Assembly Line Fast-Forward","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"반복 작업을 하는 인물 앞에 처리할 물건이 점점 빠르게 밀려온다. 숙련보다 속도가 앞서면서 생산 현장이 연쇄적인 실수와 웃음의 무대가 된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002220/index.html"},{"id":"MEJE-KW-002221","row_version":1,"title":"게임의 기존 모델로 다른 인물을 대신하기","original":"Asset Actor","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"새로운 모델을 만들지 않고 이미 있는 캐릭터나 배경 자산을 비슷한 역할에 다시 쓴다. 이야기에서 요구하는 모습과 화면에 보이는 모습 사이의 간격이 생긴다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-002221/index.html"},{"id":"MEJE-KW-002222","row_version":1,"title":"동정하기 어려운 피해자","original":"Asshole Victim","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"피해를 입었지만 이전의 잔인함이나 무례함 때문에 관객이 쉽게 연민하지 못하는 인물. 피해 사실과 그 인물의 행동에 대한 평가는 별개로 남는다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002222/index.html"},{"id":"MEJE-KW-002223","row_version":1,"title":"개성을 억누르는 학교","original":"Assimilation Academy","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"학교가 학생의 차이와 창의성을 문제로 여기고 복종과 획일성을 우선한다. 교복이나 반복 훈육이 통제의 시각적 표지가 될 수 있다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-002223/index.html"},{"id":"MEJE-KW-002224","row_version":2,"title":"흡수한 상대 때문에 동화자가 무너지기","original":"Assimilation Backfire","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"몸이나 정신을 흡수하던 존재가 뜻밖에 강한 인격이나 성질을 받아들여 스스로 혼란에 빠진다. 무조건 강해지는 동화 능력의 반대 결과다. 동화 자체를 목표로 하는 모든 사람을 하나로 합치려는 계획의 약점이 될 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002224/index.html"},{"id":"MEJE-KW-002225","row_version":3,"title":"모든 사람을 하나로 합치려는 계획","original":"Assimilation Plot","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"갈등을 없애겠다며 사람들의 마음이나 몸을 강제로 한 집단에 합치려 한다. 평화를 내세운 목적과 개인의 선택을 빼앗는 수단이 충돌한다. 무분별하게 사람을 흡수하면 흡수한 상대 때문에 동화자가 무너지기의 반격을 당할 수 있다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-002225/index.html"},{"id":"MEJE-KW-002226","row_version":2,"title":"다른 동물인 척하는 동물","original":"Ass in a Lion Skin","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"동물 캐릭터가 옷·몸짓·소리로 다른 종처럼 보이려 한다. 인간을 흉내 내는 의인화와 달리 동물 사이의 종 구분을 이용한 위장이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002226/index.html"},{"id":"MEJE-KW-002227","row_version":1,"title":"외교를 망치는 무례한 대사","original":"\"Ass\" in \"Ambassador\"","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"상대 문화와 관례를 알아야 할 외교 사절이 오만하고 무례하게 행동해 협상을 악화시킨다. 개인의 성격 문제가 국가 사이의 갈등으로 번진다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002227/index.html"},{"id":"MEJE-KW-002228","row_version":3,"title":"플레이어를 돕기 위해 잠시 등장하는 인물","original":"Assist Character","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"직접 조종하지 않는 인물이 전투 중 공격·치유·방어 등 특정 도움을 제공한다. 플레이어의 주인공이 못 하는 기능을 짧게 보완한다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-002228/index.html"},{"id":"MEJE-KW-002229","row_version":2,"title":"가장 강한 전사가 지도자가 되는 사회","original":"Asskicking Leads to Leadership","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"싸움 실력을 통치 자격의 기준으로 삼는 집단 규칙. 전투력과 협상·돌봄 능력이 다를 때 사회의 약점이 드러난다. 문화의 선악을 나눈 지혜의 도시와 전사의 도시를 맞세우기와 지도력의 기준이 연결된다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-002229/index.html"},{"id":"MEJE-KW-002230","row_version":1,"title":"싸우기 전 위압적인 자세를 잡기","original":"Ass-Kicking Pose","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물이 전투 직전 몸을 세우고 상대를 바라보며 강함을 시각적으로 예고한다. 실전 기술보다 관객과 상대에게 보내는 선언에 가깝다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-002230/index.html"},{"id":"MEJE-KW-002231","row_version":1,"title":"엉덩이로 상대를 들이받기","original":"Ass Kicks You","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 몸을 뒤로 밀어 엉덩이로 상대를 공격한다. 피해의 크기보다 예상 밖의 신체 사용과 굴욕감이 웃음을 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002231/index.html"},{"id":"MEJE-KW-002232","row_version":1,"title":"특정 감독과 늘 함께하는 작곡가","original":"Associated Composer","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"감독이나 핵심 제작자가 여러 작품에서 같은 작곡가와 꾸준히 협업한다. 음악의 특징과 영상의 방향이 반복 작업을 통해 서로 영향을 준다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-002232/index.html"},{"id":"MEJE-KW-002233","row_version":1,"title":"공통점 하나로 다른 성질까지 같다고 우기기","original":"Association Fallacy","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"두 대상이 한 가지 성질을 공유한다는 이유만으로 나머지 성질도 같다고 결론짓는다. 겉보기의 연결이 실제 논거가 되는지는 따로 검토해야 한다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002233/index.html"},{"id":"MEJE-KW-002234","row_version":1,"title":"복선 없이 갑자기 튀어나온 해결책","original":"Ass Pull","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"앞선 정보로 예측하기 어려운 물건이나 능력이 위기 순간에 나타나 문제를 단숨에 끝낸다. 뜻밖의 반전과 납득할 근거가 부족한 해결을 구분한다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-002234/index.html"},{"id":"MEJE-KW-002235","row_version":1,"title":"신체 내부에 물건을 숨기거나 꺼내기","original":"Ass Shove","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 물건을 직장에 숨기거나 꺼내는 상황을 충격이나 희극으로 사용하는 장면. 행위의 구체적인 과정보다 관객과 등장인물의 반응이 중심이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002235/index.html"},{"id":"MEJE-KW-002236","row_version":2,"title":"아홀로틀로 평온함을 보여 주기","original":"Assuaging Axolotl","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"작품 속 아홀로틀의 느린 움직임과 귀여운 외형을 휴식·회복의 이미지로 쓴다. 실제 동물의 행동을 보편적으로 단정하지 않고 화면의 상징을 다룬다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-002236/index.html"},{"id":"MEJE-KW-002237","row_version":1,"title":"상대가 다른 사람인 줄 알고 말하기","original":"Assumed It Was Someone Else","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"문 앞이나 등 뒤의 사람을 익숙한 상대라고 짐작하고 속마음을 쏟아낸 뒤 다른 인물임을 안다. 신원을 확인하기 전의 감정이 오해를 키운다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002237/index.html"},{"id":"MEJE-KW-002238","row_version":1,"title":"이긴 줄 알고 미리 축하하기","original":"Assumed Win","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"결과가 발표되기 전에 인물이 승리를 확신하고 자리에서 일어나거나 인사를 시작한다. 실제 결과가 다를 때 자신감이 당혹감으로 바뀐다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002238/index.html"},{"id":"MEJE-KW-002239","row_version":2,"title":"관객의 나이를 멋대로 정해 말 걸기","original":"Assuming the Audience's Age","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"화자나 진행자가 관객을 어린이 또는 어른이라고 가정하며 설명한다. 예상 독자층과 실제 보는 사람의 차이가 웃음이나 소외감을 만든다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002239/index.html"},{"id":"MEJE-KW-002240","row_version":1,"title":"안심시키려던 말이 불안을 키우기","original":"Assurance Backfire","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"안전을 약속하거나 좋은 예를 들려던 사람이 오히려 실패 가능성을 떠올리게 한다. 말한 사람의 의도와 듣는 사람의 해석이 엇갈린다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002240/index.html"},{"id":"MEJE-KW-002241","row_version":3,"title":"소행성에서 자원을 캐는 사람들","original":"Asteroid Miners","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"소행성을 오가며 광물과 물자를 채굴하는 인물이나 공동체. 외딴 작업장과 이동 비용이 독립적인 생활 방식과 위험을 만든다. 채굴 작업의 이동 환경에는 바위가 빽빽한 소행성 길 같은 장애물을 둘 수 있다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-002241/index.html"},{"id":"MEJE-KW-002242","row_version":1,"title":"쓰러뜨리면 여러 개로 갈라지는 적","original":"Asteroids Monster","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"큰 적을 공격해 없애면 작은 적들이 나와 다시 싸워야 한다. 한 번의 승리가 적의 수를 늘려 전투 순서를 바꾸는 게임 규칙이다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-002242/index.html"},{"id":"MEJE-KW-002243","row_version":2,"title":"바위가 빽빽한 소행성 길","original":"Asteroid Thicket","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"우주선이 좁은 틈을 비행하며 충돌을 피해야 하는 밀집 소행성대 묘사. 우주의 실제 밀도보다 추격 장면의 장애물로서 기능한다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-002243/index.html"},{"id":"MEJE-KW-002244","row_version":1,"title":"경전 구절로 말의 무게를 더하기","original":"As the Good Book Says...","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 상황에 맞는 성서 구절을 인용해 행동을 정당화하거나 장면에 엄숙함을 준다. 인용의 적절성과 화자의 의도는 별도로 살핀다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002244/index.html"},{"id":"MEJE-KW-002245","row_version":1,"title":"천식 발작을 위기 장치로 쓰기","original":"Asthma Peril","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 위험한 순간 호흡 곤란을 겪고 필요한 도움을 얻기 어려워진다. 실제 천식의 경과를 설명하기보다 작품이 질환을 긴장 요소로 쓰는 방식을 다룬다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002245/index.html"},{"id":"MEJE-KW-002246","row_version":1,"title":"능력과 외모가 지나치게 잘 맞기","original":"Astonishingly Appropriate Appearance","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"불을 다루는 인물에게 불꽃 같은 머리색을 주는 식으로 성격·능력과 외형을 노골적으로 맞춘다. 한눈에 알아보게 하는 디자인과 우연처럼 보이는 설정 사이의 간격이다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-002246/index.html"},{"id":"MEJE-KW-002247","row_version":1,"title":"때맞춘 말 끊기가 문장을 완성하기","original":"Astonishingly Appropriate Interruption","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 말을 잇던 순간 사건이나 다른 인물의 외침이 끼어들어 앞 문장의 빈자리를 우연히 채운다. 대화의 중단이 새로운 뜻을 만든다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002247/index.html"},{"id":"MEJE-KW-002248","row_version":1,"title":"이세계 바닥에 반복되는 바둑판 무늬","original":"Astral Checkerboard Decor","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"정신 세계나 낯선 차원의 바닥·벽에 검고 흰 격자를 넓게 배치한다. 규칙적인 문양이 익숙하지 않은 공간의 인상을 만든다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-002248/index.html"},{"id":"MEJE-KW-002249","row_version":3,"title":"마지막 무대를 우주로 옮기기","original":"Astral Finale","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"이야기의 끝에서 갈등의 장소가 행성 밖이나 달로 확대된다. 공간의 규모를 키워 결말의 중요성과 장관을 강조한다. 넓은 공간에서 작은 인물로 들어오는 우주에서 작은 장소까지 단숨에 당겨 보기가 규모를 전달한다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-002249/index.html"},{"id":"MEJE-KW-002250","row_version":2,"title":"몸을 떠나 움직이는 의식","original":"Astral Projection","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"인물의 정신이나 영혼이 몸과 분리돼 다른 장소를 돌아다닌다. 남겨진 몸의 상태와 분리된 의식의 감각·위험이 세계의 규칙이 된다. 몸을 벗어난 의식과 존재 자체가 바뀌는 더 높은 존재 단계로 올라가기는 다르다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-002250/index.html"},{"id":"MEJE-KW-002251","row_version":1,"title":"아톰을 떠올리게 하는 로봇 소년","original":"Astro Clone","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":null,"parent_id":null,"tag_path":["ML-F29"],"summary":"어린 로봇의 디자인과 인간이 되고 싶은 마음을 통해 아톰의 문화적 이미지를 떠올리게 한다. 특정 작품의 장면을 그대로 옮기기보다 후대 창작물의 참조 방식을 설명한다.","accent":"#7B876E","tab":"#9A6A55","facet":"기원·전승·참조","bookmark":"분류축","entry_url":"cards/MEJE-KW-002251/index.html"},{"id":"MEJE-KW-002252","row_version":2,"title":"별의 움직임을 읽는 점성술사","original":"Astrologer","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"별자리와 행성의 배치를 사건과 인물의 운명에 연결해 해석하는 캐릭터. 작품 속 예언의 실제 효력은 세계관 규칙에 따라 달라진다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002252/index.html"},{"id":"MEJE-KW-002253","row_version":2,"title":"우주에서 작은 장소까지 단숨에 당겨 보기","original":"Astronomic Zoom","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"행성이나 은하에서 출발한 화면이 한 거리·방·인물로 빠르게 좁혀진다. 광대한 규모와 사적인 이야기를 한 움직임으로 연결한다. 공간의 분위기를 부분으로 소개하는 장소의 일부를 모아 보여 주는 도입 장면과 화면의 출발점이 다르다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-002253/index.html"},{"id":"MEJE-KW-002254","row_version":1,"title":"민심처럼 꾸민 조직적 홍보","original":"AstroTurf","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"기업이나 정치 조직이 자발적 지지처럼 보이는 글·모임·반응을 만들어 낸다. 실제 참여자의 의사와 계획된 홍보 활동을 구분하는 장치다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-002254/index.html"},{"id":"MEJE-KW-002255","row_version":1,"title":"한쪽 팔만 과하게 발달한 몸","original":"Asymmetrically Jacked","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"인물의 팔이나 다리 한쪽만 유난히 크고 강하게 그려 반복한 행동이나 능력을 시각적으로 암시한다. 비대칭이 만화식 과장인지 설정상 변화인지 살핀다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-002255/index.html"},{"id":"MEJE-KW-002256","row_version":1,"title":"사소한 고민 뒤에 심각한 문제를 덧붙이기","original":"Asymmetric Dilemma","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"두 문제를 비슷한 무게로 말하다가 뒤쪽에서 훨씬 큰 위기를 드러낸다. 먼저 길게 설명한 작은 걱정이 우스워지는 대화 반전이다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002256/index.html"},{"id":"MEJE-KW-002257","row_version":3,"title":"서로 다른 역할로 겨루는 멀티플레이","original":"Asymmetric Multiplayer","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"같은 게임에 참여한 플레이어들이 능력·목표·조작 방식이 다른 역할을 맡는다. 단순한 외형 차이가 아니라 각자의 경험과 전략이 달라진다. 서로 다른 진영이 경쟁하는 경우에는 비대칭 대전 태그로도 찾을 수 있다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-002257/index.html"},{"id":"MEJE-KW-002258","row_version":1,"title":"둘 다 아는 정보를 굳이 서로 설명하기","original":"As You Know","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"등장인물들이 이미 공유한 사실을 다시 말해 관객에게 설정을 전달한다. 전달해야 할 정보와 인물 사이의 자연스러운 대화가 충돌한다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002258/index.html"},{"id":"MEJE-KW-002259","row_version":1,"title":"팔을 뻗어 작은 상대를 막아 두기","original":"At Arm's Length","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"키가 큰 인물이 손으로 작은 상대를 밀어 거리를 유지해 공격이 닿지 않게 한다. 신체 차이가 폭력보다 익살스러운 제압으로 표현된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002259/index.html"},{"id":"MEJE-KW-002260","row_version":1,"title":"총기 자살 시도를 보여 주는 장면","original":"Ate His Gun","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물의 절망이나 관계의 위기를 드러내기 위해 총기를 이용한 자살 시도를 암시하거나 묘사한다. 구체적인 방법보다 사건의 맥락과 주변 인물에게 남는 영향을 다룬다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002260/index.html"},{"id":"MEJE-KW-002261","row_version":2,"title":"함께 먹을 음식을 혼자 다 먹기","original":"Ate It All","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"여럿이 나눌 음식에 손을 댄 인물이 조금씩 더 먹다가 결국 모두 없앤다. 계획하지 않은 과식이 모임의 갈등이나 웃음을 만든다. 먹을 수 없는 물건까지 삼키는 음식과 그릇까지 먹어 버리기는 식성의 과장이 더 크다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002261/index.html"},{"id":"MEJE-KW-002262","row_version":2,"title":"음식과 그릇까지 먹어 버리기","original":"Ate the Plate","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 음식뿐 아니라 접시·포장지 같은 용기까지 삼킨다. 허기나 비범한 식성, 현실과 다른 몸의 규칙을 짧게 보여 준다. 내용물의 성질 때문에 도구가 변형되는 숟가락까지 녹이는 음식과 구분한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002262/index.html"},{"id":"MEJE-KW-002263","row_version":1,"title":"숟가락까지 녹이는 음식","original":"Ate the Spoon","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"음식이나 물질에 담갔던 숟가락이 변형되거나 사라져 내용물의 강도를 암시한다. 실제 조리법보다 과장된 반응을 보여 주는 소품 연출이다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-002263/index.html"},{"id":"MEJE-KW-002264","row_version":2,"title":"지혜의 도시와 전사의 도시를 맞세우기","original":"Athens and Sparta","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"한 도시는 학문·예술과 평화를, 다른 도시는 군사력과 엄격한 훈련을 대표하도록 설계한다. 실제 역사 속 도시를 단순한 선악의 두 유형으로 환원하지 않는 것이 중요하다. 가장 강한 전사가 지도자가 되는 사회는 전사 중심 도시의 통치 원리가 될 수 있다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-002264/index.html"},{"id":"MEJE-KW-002265","row_version":2,"title":"운동만 하면 서투른 인물","original":"Athletically Challenged","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"평소에는 능숙해 보여도 공을 다루거나 몸을 맞춰 움직이는 활동에는 유난히 서툰 캐릭터. 한 가지 운동 실력과 인물 전체의 가치 판단을 구분한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002265/index.html"},{"id":"MEJE-KW-002266","row_version":1,"title":"경기장처럼 꾸민 게임 구간","original":"Athletic Arena Level","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임의 한 단계가 야구장·체육관·경기장을 배경으로 삼고 운동 장비나 규칙을 장애물로 쓴다. 스포츠 대회 자체를 플레이하는 게임과 구분된다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-002266/index.html"},{"id":"MEJE-KW-002267","row_version":2,"title":"가라앉은 고대 문명 아틀란티스","original":"Atlantis","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"바다 아래 사라진 문명을 이야기의 배경이나 탐사 대상으로 사용한다. 기술·마법·몰락의 이유는 작품마다 달라지는 설정 요소다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-002267/index.html"},{"id":"MEJE-KW-002268","row_version":1,"title":"거대한 물체를 어깨에 떠받치는 자세","original":"Atlas Pose","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물이 자신의 몸보다 훨씬 큰 물체를 머리와 어깨에 걸쳐 버틴다. 힘의 크기를 한눈에 보여 주는 조각 같은 자세다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-002268/index.html"},{"id":"MEJE-KW-002269","row_version":1,"title":"나쁜 일도 솔직히 인정한다며 변명하기","original":"At Least I Admit It","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 잘못을 지적받자 숨기지 않는다는 점을 내세워 자신이 더 낫다고 주장한다. 솔직함이 행동의 피해를 없애 주는지는 별개의 문제다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002269/index.html"},{"id":"MEJE-KW-002270","row_version":2,"title":"행성의 대기를 무기로 바꾸기","original":"Atmosphere Abuse","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"강한 존재가 행성 전체의 공기 성질이나 양을 바꿔 넓은 지역을 위협한다. 개별 상대를 공격하는 능력과 다른 규모의 환경 조작이다. 환경 전체의 인공 설비인 인위적으로 만든 태양과 함께 행성의 유지 조건을 정할 수 있다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-002270/index.html"},{"id":"MEJE-KW-002271","row_version":1,"title":"욕설 한마디를 거대한 외침으로 만들기","original":"Atomic F-Bomb","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"분노나 놀람이 절정에 이른 순간 한 단어를 지나치게 크게 외친다. 어휘보다 소리의 크기와 타이밍이 장면의 충격을 만든다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-002271/index.html"},{"id":"MEJE-KW-002272","row_version":3,"title":"핵무기를 파멸의 상징으로 그리기","original":"Atomic Hate","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18"],"summary":"핵무기를 도시와 사회의 붕괴를 단번에 떠올리게 하는 위협으로 사용한다. 실제 피해의 역사와 허구의 장관을 혼동하지 않고 서사의 공포 표현을 살핀다. 핵에너지를 개인의 힘으로 바꾼 원자력 현상을 능력으로 쓰는 인물과 위협의 규모가 다르다.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/MEJE-KW-002272/index.html"},{"id":"MEJE-KW-002273","row_version":2,"title":"원자력 현상을 능력으로 쓰는 인물","original":"Atomic Superpower","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"방사선이나 핵에너지의 이미지를 공격과 방어 능력으로 바꾼 캐릭터. 과학적 작동 설명보다 작품이 정한 힘의 범위와 대가가 중요하다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-002273/index.html"},{"id":"MEJE-KW-002274","row_version":1,"title":"죄책감 때문에 범인을 잡는 탐정","original":"Atonement Detective","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"과거에 사람을 죽인 경험을 짊어진 수사자가 다른 범죄를 막으며 속죄하려 한다. 사건 해결과 자기 용서는 같은 결과가 아닐 수 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002274/index.html"},{"id":"MEJE-KW-002275","row_version":2,"title":"시신 더미 위에 선 승리자","original":"Atop a Mountain of Corpses","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"많은 적을 쓰러뜨린 인물이 쌓인 시신 위에서 승리의 자세를 취한다. 전투의 규모를 보여 주는 동시에 승리의 비용을 드러낼 수 있다. 전쟁의 피해를 넓게 보여 주는 참상을 빠르게 이어 보여 주는 몽타주와 시각적 역할이 다르다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-002275/index.html"},{"id":"MEJE-KW-002276","row_version":1,"title":"우스꽝스러운 영웅 이름","original":"Atrocious Alias","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"능력과 복장은 갖췄지만 별명이 진지한 이미지와 어긋나 주변의 웃음을 사는 인물. 이름의 인상이 사회적 인정에 영향을 준다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002276/index.html"},{"id":"MEJE-KW-002277","row_version":1,"title":"절지동물을 괴물로 그리기","original":"Atrocious Arthropods","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"거미·전갈·곤충의 생김새를 공포와 악의의 짧은 기호로 반복 사용한다. 실제 종의 생태와 작품이 만든 위협 이미지를 구분한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-002277/index.html"},{"id":"MEJE-KW-002278","row_version":1,"title":"참상을 빠르게 이어 보여 주는 몽타주","original":"Atrocity Montage","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"여러 장소의 파괴와 피해를 짧은 장면들로 연결해 한 세력이나 사건의 규모를 보여 준다. 단일 사건보다 반복과 누적이 감정적 충격을 만든다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-002278/index.html"},{"id":"MEJE-KW-002279","row_version":3,"title":"때리면 성질이 바뀌는 게임 아이템","original":"Attackable Pickup","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"바닥의 획득 물건을 먼저 공격하면 효과나 가치가 달라진다. 바로 줍는 선택과 변화를 노리는 위험이 함께 생긴다. 성공 여부에 따라 손해가 생기는 빗나간 공격이 자신에게 피해를 주기와 함께 위험 보상 규칙을 이룬다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-002279/index.html"},{"id":"MEJE-KW-002280","row_version":2,"title":"조련사의 지시에 싸우는 동물","original":"Attack Animal","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"사람의 명령을 받아 함께 싸우는 동물이나 이에 준하는 생명체. 스스로 판단하는 동료와 조련사가 통제하는 전투 수단을 구분한다. 동물을 은밀한 수단으로 쓰는 암살 수단으로 쓰인 동물은 이 관계의 한 변형이다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-002280/index.html"},{"id":"MEJE-KW-002281","row_version":2,"title":"물러서지 않고 계속 공격하는 인물","original":"Attack! Attack! Attack!","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"큰 손실을 겪어도 후퇴보다 공격을 반복하는 전투 태도. 용기·집착·퇴로의 부재 가운데 무엇이 원인인지에 따라 의미가 달라진다. 상황이 뒤집힐 때는 돌격을 외치다 갑자기 후퇴를 외치기가 반대 선택을 드러낸다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002281/index.html"},{"id":"MEJE-KW-002282","row_version":1,"title":"돌격을 외치다 갑자기 후퇴를 외치기","original":"Attack! Attack... Retreat! Retreat!","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"공격을 독려하던 인물이 더 큰 위협을 보자 같은 박자로 반대 명령을 외친다. 급한 태도 변화가 전투의 긴장과 웃음을 함께 만든다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002282/index.html"},{"id":"MEJE-KW-002283","row_version":2,"title":"빗나간 공격이 자신에게 피해를 주기","original":"Attack Backfire","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"공격에 실패했을 때 기회만 잃는 것이 아니라 사용자가 반동이나 사고의 피해까지 입는다. 강한 기술을 고를수록 실패 위험을 계산하게 한다. 공격이 실패할 확률을 두는 공격이 빗나갈 확률을 둔 규칙에 실패의 대가를 더한다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-002283/index.html"},{"id":"MEJE-KW-002284","row_version":1,"title":"원격으로 싸우는 공격 드론","original":"Attack Drone","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"센서와 이동 장치를 갖춘 무인 무기가 조종자나 자동 시스템의 명령으로 공격한다. 전투 인원의 위험을 줄이는 대신 통제와 책임의 문제가 생긴다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-002284/index.html"}]}.cards;